export function nomeGara(id: string): string {
  return GARE_GP.find(g => g.id === id)?.nome ?? id;
}

/** Le vittorie nei grandi premi di un cavallo. */
export function palmares(nome: string, anno?: number | null): VittoriaGP[] {
  const n = nome.trim().toUpperCase();
  return VITTORIE_GP
    .filter(v => v.vincitore === n && (anno == null || v.nato == null || v.nato === anno))
    .sort((a, b) => a.anno - b.anno || a.gara.localeCompare(b.gara));
}
